/* eslint-disable */
/* global WebImporter */

/**
 * Parser: testimonial (block table "Testimonial").
 * Source: https://www.amag.ch/de/garagenuebersicht/garage-buelach.html — `.amag-quoteContainer`
 * (section 13, customer quote).
 *
 * Authoring row (blocks/testimonial/testimonial.js): ONE row, paragraphs in order —
 *   <p>quote</p><p>author</p><p>customer-of line</p>
 * (the curly quotes are generated by CSS, never authored).
 * The block holds a single quote: the active carousel item (fallback: the first) is used.
 * Dropped: carousel arrows, "1 /" counter and the hidden indicator label list
 * (`ol.cmp-carousel__indicators.d-none`, which carries a stale name "Thorben W.").
 */
const txt = (n) => (n ? n.textContent.replace(/\s+/g, ' ').trim() : '');
const mk = (document, tag, ...kids) => {
  const e = document.createElement(tag);
  kids.flat().forEach((k) => { if (k != null && k !== '') e.append(k); });
  return e;
};

export default function parse(element, { document }) {
  const item = element.querySelector('.cmp-carousel__item--active .amag-quoteModul')
    || element.querySelector('.amag-quoteModul')
    || element;
  const quote = txt(item.querySelector('.amag-quoteModul__qoute, .amag-quoteModul__quote, blockquote'))
    .replace(/^[„“"«»]+|[“”"«»]+$/g, '').trim();
  const author = txt(item.querySelector('.amag-quoteModul__author'));
  const customer = txt(item.querySelector('.amag-quoteModul__customerBy'));

  if (!quote) {
    element.replaceWith(...element.childNodes);
    return;
  }

  const cell = [mk(document, 'p', quote)];
  if (author) cell.push(mk(document, 'p', author));
  if (customer) cell.push(mk(document, 'p', customer));

  const cells = [[cell]];
  const block = WebImporter.Blocks.createBlock(document, { name: 'Testimonial', cells });
  element.replaceWith(block);
}
